mapper.select:
SELECT  FROM problem

ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE problem_version SET status = 'VALIDATING', updated_at = #{updatedAt}, row_version = row_version + 1
WHERE id = UUID_TO_BIN(#{versionId}) AND problem_id = UUID_TO_BIN(#{problemId})
  AND status = 'DRAFT' AND row_version = #{expectedRowVersion}

UPDATE problem_version SET status = #{targetStatus}, updated_at = #{updatedAt}, row_version = row_version + 1
WHERE id = UUID_TO_BIN(#{versionId}) AND problem_id = UUID_TO_BIN(#{problemId})
  AND status = 'VALIDATING' AND row_version = #{expectedRowVersion}
